def demo(app):
    for member in samples("members.json"):
        app.add_member(**member)
    app.create_activity(**samples("activity.json"))
    app.enroll(**samples("enrollment.json"))
    # 2026-10-15 的虚构安排：A-002 与 A-001 同日，由小陈和小周报满；
